import { defineConfig } from 'vite'
import { tanstackStart } from '@tanstack/react-start/plugin/vite'
import viteReact from '@vitejs/plugin-react'
import tsconfigPaths from 'vite-tsconfig-paths'

export default defineConfig({
  server: {
    port: 47821,
  },
  plugins: [
    tsconfigPaths(),
    tanstackStart(),
    viteReact(),
  ],
})

import { defineConfig } from '@tanstack/react-start/config'

export default defineConfig({
  server: {
    preset: 'node-server',
  },
})

import { createRouter } from '@tanstack/react-router'
import { routeTree } from './routeTree.gen'

export function getRouter() {
  const router = createRouter({
    routeTree,
    scrollRestoration: true,
  })

  return router
}

export interface Comment {
  id: string;
  parentId: string | null;
  body: string;
  createdAt: number;
}

export interface CreateCommentRequest {
  parentId: string | null;
  body: string;
}

import type { Comment } from '../types'

// In-memory comment store (survives between HTTP requests for lifetime of server process)
const comments: Comment[] = []
let nextId = 1

export function getAllComments(): Comment[] {
  return [...comments]
}

export function createComment(body: string, parentId: string | null): Comment {
  const comment: Comment = {
    id: String(nextId++),
    parentId,
    body,
    createdAt: Date.now(),
  }
  comments.push(comment)
  return comment
}

import { createFileRoute } from '@tanstack/react-router'
import { getAllComments, createComment } from '../../server/store'

export const Route = createFileRoute('/api/comments')({
  server: {
    handlers: {
      GET: async () => {
        const comments = getAllComments()
        return new Response(JSON.stringify(comments), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        })
      },
      POST: async ({ request }) => {
        const url = new URL(request.url)
        const shouldFail = url.searchParams.get('fail') === '1'

        // Artificial delay of at least 300ms so optimistic update is observable
        await new Promise((resolve) => setTimeout(resolve, 350))

        if (shouldFail) {
          return new Response(
            JSON.stringify({ error: 'Internal Server Error' }),
            {
              status: 500,
              headers: { 'Content-Type': 'application/json' },
            },
          )
        }

        const body = (await request.json()) as {
          parentId: string | null
          body: string
        }

        const comment = createComment(body.body, body.parentId)

        return new Response(JSON.stringify(comment), {
          status: 200,
          headers: { 'Content-Type': 'application/json' },
        })
      },
    },
  },
})

