import { createFileRoute } from '@tanstack/react-router'
import { useState } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import { useComments, useCreateComment } from '../hooks/useComments'
import { CommentTree } from '../components/CommentTree'
import { CommentForm } from '../components/CommentForm'

export const Route = createFileRoute('/')({
  component: Home,
})

function Home() {
  const { data: comments = [], isLoading, error } = useComments()
  const createComment = useCreateComment()
  const queryClient = useQueryClient()
  const [replyTo, setReplyTo] = useState<string | null>(null)
  const [statusMessage, setStatusMessage] = useState<string | null>(null)

  const handleCreateComment = async (body: string, parentId: string | null) => {
    setStatusMessage(null)
    try {
      await createComment.mutateAsync({ body, parentId })
      setReplyTo(null)
    } catch {
      setStatusMessage('Error: Failed to create comment (server returned an error)')
    }
  }

  const handleCreateFailingComment = async (
    body: string,
    parentId: string | null,
  ) => {
    setStatusMessage(null)
    try {
      await createComment.mutateAsync({ body, parentId, fail: true })
    } catch {
      setStatusMessage('Error: Failed to create comment (server returned an error)')
    }
  }

  if (isLoading) {
    return (
      <div style={{ padding: '1rem', fontFamily: 'sans-serif' }}>
        <h1>Comment Thread</h1>
        <p>Loading comments...</p>
      </div>
    )
  }

  if (error) {
    return (
      <div style={{ padding: '1rem', fontFamily: 'sans-serif' }}>
        <h1>Comment Thread</h1>
        <p style={{ color: 'red' }}>Error loading comments.</p>
      </div>
    )
  }

  return (
    <div style={{ padding: '1rem', fontFamily: 'sans-serif', maxWidth: '700px', margin: '0 auto' }}>
      <h1>Comment Thread</h1>

      {statusMessage && (
        <p style={{ color: 'red', fontWeight: 'bold' }}>{statusMessage}</p>
      )}

      <CommentForm
        onSubmit={(body) => handleCreateComment(body, null)}
        placeholder="Write a top-level comment..."
        label="Post Comment"
      />

      <div style={{ marginTop: '1rem' }}>
        <button
          type="button"
          onClick={async () => {
            setStatusMessage(null)
            try {
              await createComment.mutateAsync({
                body: 'This comment will fail!',
                parentId: null,
                fail: true,
              })
            } catch {
              setStatusMessage(
                'Error: Failed to create comment (server returned an error)',
              )
            }
          }}
          style={{
            padding: '0.5rem 1rem',
            background: '#dc3545',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '0.9rem',
          }}
        >
          Test Error Path (POST with fail=1)
        </button>
      </div>

      <div style={{ marginTop: '1.5rem' }}>
        {comments.length === 0 ? (
          <p style={{ color: '#666' }}>No comments yet. Be the first!</p>
        ) : (
          <CommentTree
            comments={comments}
            parentId={null}
            replyTo={replyTo}
            onReply={setReplyTo}
            onSubmitReply={handleCreateComment}
          />
        )}
      </div>
    </div>
  )
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import type { Comment } from '../types'

const COMMENTS_QUERY_KEY = ['comments'] as const

async function fetchComments(): Promise<Comment[]> {
  const res = await fetch('/api/comments')
  if (!res.ok) {
    throw new Error('Failed to fetch comments')
  }
  return res.json()
}

async function postComment({
  body,
  parentId,
  fail,
}: {
  body: string
  parentId: string | null
  fail?: boolean
}): Promise<Comment> {
  const url = fail ? '/api/comments?fail=1' : '/api/comments'
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ body, parentId }),
  })
  if (!res.ok) {
    throw new Error('Failed to create comment')
  }
  return res.json()
}

export function useComments() {
  return useQuery({
    queryKey: COMMENTS_QUERY_KEY,
    queryFn: fetchComments,
    staleTime: 0,
  })
}

export function useCreateComment() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: postComment,

    onMutate: async (newComment) => {
      // Cancel any in-flight queries for comments
      await queryClient.cancelQueries({ queryKey: COMMENTS_QUERY_KEY })

      // Snapshot the current cache
      const previousComments = queryClient.getQueryData<Comment[]>(
        COMMENTS_QUERY_KEY,
      )

      // Optimistically insert the new comment into the cache
      if (previousComments) {
        const optimisticComment: Comment = {
          id: `optimistic-${Date.now()}-${Math.random().toString(36).slice(2)}`,
          parentId: newComment.parentId,
          body: newComment.body,
          createdAt: Date.now(),
        }

        queryClient.setQueryData<Comment[]>(COMMENTS_QUERY_KEY, [
          ...previousComments,
          optimisticComment,
        ])
      }

      // Return the snapshot for rollback
      return { previousComments }
    },

    onError: (_error, _newComment, context) => {
      // Roll back to the pre-mutation snapshot
      if (context?.previousComments) {
        queryClient.setQueryData<Comment[]>(
          COMMENTS_QUERY_KEY,
          context.previousComments,
        )
      }
    },

    onSettled: () => {
      // Invalidate to re-sync with the server
      queryClient.invalidateQueries({ queryKey: COMMENTS_QUERY_KEY })
    },
  })
}

import type { Comment } from '../types'
import { CommentForm } from './CommentForm'

interface CommentTreeProps {
  comments: Comment[]
  parentId: string | null
  depth?: number
  replyTo: string | null
  onReply: (id: string | null) => void
  onSubmitReply: (body: string, parentId: string | null) => Promise<void>
}

export function CommentTree({
  comments,
  parentId,
  depth = 0,
  replyTo,
  onReply,
  onSubmitReply,
}: CommentTreeProps) {
  const children = comments.filter((c) => c.parentId === parentId)

  if (children.length === 0) return null

  return (
    <ul
      style={{
        listStyle: 'none',
        padding: 0,
        margin: 0,
        marginLeft: depth > 0 ? '1.5rem' : 0,
        borderLeft: depth > 0 ? '2px solid #e0e0e0' : 'none',
        paddingLeft: depth > 0 ? '1rem' : 0,
      }}
    >
      {children.map((comment) => (
        <li key={comment.id} style={{ marginBottom: '0.75rem' }}>
          <div
            style={{
              padding: '0.75rem',
              border: '1px solid #ddd',
              borderRadius: '6px',
              background: comment.id.startsWith('optimistic-')
                ? '#fffde7'
                : '#fff',
            }}
          >
            <p
              style={{
                margin: 0,
                fontSize: '0.95rem',
                lineHeight: '1.5',
              }}
            >
              {comment.body}
            </p>
            <div
              style={{
                marginTop: '0.5rem',
                display: 'flex',
                gap: '0.75rem',
                alignItems: 'center',
                fontSize: '0.8rem',
                color: '#888',
              }}
            >
              <span>
                {new Date(comment.createdAt).toLocaleString()}
              </span>
              {comment.id.startsWith('optimistic-') && (
                <span style={{ color: '#f0a500', fontWeight: 'bold' }}>
                  (optimistic)
                </span>
              )}
              <button
                type="button"
                onClick={() =>
                  onReply(replyTo === comment.id ? null : comment.id)
                }
                style={{
                  background: 'none',
                  border: 'none',
                  color: '#0066cc',
                  cursor: 'pointer',
                  fontSize: '0.8rem',
                  textDecoration: 'underline',
                }}
              >
                Reply
              </button>
            </div>

            {replyTo === comment.id && (
              <div style={{ marginTop: '0.5rem' }}>
                <CommentForm
                  onSubmit={async (body) => {
                    await onSubmitReply(body, comment.id)
                  }}
                  placeholder={`Reply to "${comment.body.slice(0, 30)}${comment.body.length > 30 ? '...' : ''}"`}
                  label="Post Reply"
                />
              </div>
            )}
          </div>

          {/* Recursively render children */}
          <CommentTree
            comments={comments}
            parentId={comment.id}
            depth={depth + 1}
            replyTo={replyTo}
            onReply={onReply}
            onSubmitReply={onSubmitReply}
          />
        </li>
      ))}
    </ul>
  )
}

import { useState } from 'react'

interface CommentFormProps {
  onSubmit: (body: string) => Promise<void>
  placeholder: string
  label: string
}

export function CommentForm({
  onSubmit,
  placeholder,
  label,
}: CommentFormProps) {
  const [body, setBody] = useState('')
  const [submitting, setSubmitting] = useState(false)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    const trimmed = body.trim()
    if (!trimmed) return

    setSubmitting(true)
    try {
      await onSubmit(trimmed)
      setBody('')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <form
      onSubmit={handleSubmit}
      style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}
    >
      <textarea
        value={body}
        onChange={(e) => setBody(e.target.value)}
        placeholder={placeholder}
        rows={2}
        style={{
          padding: '0.5rem',
          border: '1px solid #ccc',
          borderRadius: '4px',
          fontSize: '0.9rem',
          fontFamily: 'sans-serif',
          resize: 'vertical',
        }}
      />
      <button
        type="submit"
        disabled={submitting || !body.trim()}
        style={{
          alignSelf: 'flex-start',
          padding: '0.4rem 1rem',
          background: submitting || !body.trim() ? '#ccc' : '#007bff',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: submitting || !body.trim() ? 'not-allowed' : 'pointer',
          fontSize: '0.85rem',
        }}
      >
        {submitting ? 'Posting...' : label}
      </button>
    </form>
  )
}

